-- Frozen rollback snapshot for §190. Generated from cloud before any persistent write.
CREATE TEMP TABLE _taxonomy_nature_forme_before_state (
  object_id TEXT PRIMARY KEY,
  domain TEXT NOT NULL,
  old_ref_code_id UUID NOT NULL,
  old_code TEXT NOT NULL,
  old_source TEXT,
  old_note TEXT,
  target_code TEXT NOT NULL
) ON COMMIT DROP;


DO $before_state_gate$
DECLARE
  v_total INTEGER;
  v_legacy INTEGER;
BEGIN
  SELECT count(*),
         count(*) FILTER (WHERE old_code IN ('gite_villa', 'bungalow_chalet'))
  INTO v_total, v_legacy
  FROM _taxonomy_nature_forme_before_state;

  IF (v_total, v_legacy) IS DISTINCT FROM (243, 231) THEN
    RAISE EXCEPTION
      'taxonomy rollback snapshot mismatch: total=%, legacy=% (expected 243/231)',
      v_total, v_legacy;
  END IF;
END
$before_state_gate$;
